<?php require_once '../includes/auth.php';require_admin();verify_csrf();$id=(int)($_POST['id']??0);$a=$_POST['action']??'';if($id===user()['id'])exit('You cannot change your own access.');if($a==='set_role'){ $roles=['staff','authorized_staff','sub_officer','school_superintendent','hostel_superintendent','admin']; $role=$_POST['role']??'staff'; if(!in_array($role,$roles,true)) exit('Invalid role.'); $s=mysqli_prepare($conn,"UPDATE users SET role=? WHERE id=?"); mysqli_stmt_bind_param($s,'si',$role,$id); mysqli_stmt_execute($s); log_activity('updated','users','Assigned role '.$role,$id); flash('success','User role updated.'); redirect('users.php'); }if($a==='approve'||$a==='reject'){$st=$a==='approve'?'approved':'rejected';$s=mysqli_prepare($conn,"UPDATE users SET approval_status=?,approved_by=?,approved_at=IF(?='approved',NOW(),NULL) WHERE id=?");$uid=user()['id'];mysqli_stmt_bind_param($s,'sisi',$st,$uid,$st,$id);mysqli_stmt_execute($s);}elseif($a==='block'||$a==='unblock'){$status=$a==='block'?'blocked':'active';$s=mysqli_prepare($conn,"UPDATE users SET status=? WHERE id=?");mysqli_stmt_bind_param($s,'si',$status,$id);mysqli_stmt_execute($s);}log_activity('status_changed','users','Changed user '.$id.' to '.$a,$id);flash('success','User action completed.');redirect('users.php');
